# We'll use NCBI efetch to download sequences in batches and count N's.

import requests
import time
from io import StringIO

def fetch_sequences_batch(accessions, retries=3):
    """Fetch sequences from NCBI efetch API for a batch of accessions."""
    url = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi"
    params = {
        "db": "nucleotide",
        "id": ",".join(accessions),
        "rettype": "fasta",
        "retmode": "text"
    }

    for attempt in range(retries):
        try:
            response = requests.get(url, params=params, timeout=120)
            response.raise_for_status()
            return response.text
        except Exception as e:
            if attempt < retries - 1:
                time.sleep(5 * (attempt + 1))
            else:
                print(f"Failed to fetch batch after {retries} attempts: {e}")
                return None

def parse_fasta(fasta_text):
    """Parse FASTA text and return dict of accession -> sequence."""
    sequences = {}
    current_acc = None
    current_seq = []

    for line in fasta_text.split("\n"):
        if line.startswith(">"):
            if current_acc:
                sequences[current_acc] = "".join(current_seq)
            # Extract accession from header
            header = line[1:].split()[0]
            current_acc = header
