3074:             else:
3075:                 # For max comparison, use start of year (Jan 1)
3076:                 result = datetime(year, 1, 1)
3077:                 logger.debug("Parsed year-only date '%s' as %s (start of year for max comparison)", 
3078:                            date_str, result)
3079:             return result
3080:             
3081:         elif year_month_match:
3082:             # Year-month date like "2015-06"
3083:             year = int(year_month_match.group(1))
3084:             month = int(year_month_match.group(2))
3085:             if for_min_comparison:
3086:                 # For min comparison, use end of month
3087:                 _, last_day = calendar.monthrange(year, month)
3088:                 result = datetime(year, month, last_day)
3089:                 logger.debug("Parsed year-month date '%s' as %s (end of month for min comparison)", 
3090:                            date_str, result)
3091:             else:
3092:                 # For max comparison, use start of month
